arguments.command:
python3 -c "
import pandas as pd
import numpy as np
invoices = pd.read_csv('/app/dataset/invoices.csv')

def leading_digit(x):
    s = str(x).lstrip('0').lstrip('.')
    for ch in s:
        if ch.isdigit() and ch != '0':
            return int(ch)
    return None

invoices['lead'] = invoices['net_amount'].apply(leading_digit)
print(invoices['lead'].value_counts(normalize=True).sort_index())

benford = {d: np.log10(1+1/d) for d in range(1,10)}
print(benford)
"

